  for name,value in {'dfma_cup_port_width':24,'dfma_cup_port_length':40,'dfma_cup_port_radius':3,'dfma_cup_port_start_y':-44.2,'dfma_cup_port_inner_radius':30.1,'dfma_cup_port_radial_depth':21}.items():g.parameter(name,value,comment='DFMA proposal connector opening. Width and corner radius preserve the original connector passage; independent of baseline pc parameters.')
